                    cards.Add(new Card{recipe=new EquipmentRecipe{id="family "+family+" / angle "+angle*90,name=MeleeWeaponCatalog.English(item.family),japanese=MeleeWeaponCatalog.Japanese(item.family)},mesh=Render(root)});
                }
