                for(int cls=0;cls<6;cls++){var signatures=new HashSet<string>();foreach(var product in DistinctEquipmentDesigns.Guns)if(!product.legendary&&product.maker==maker&&product.gunClass==cls&&product.seriesVariant==0){var sample=Arsenal.FromRecipe(product,Rarity.Common);signatures.Add(sample.damage.ToString("F3")+"/"+sample.interval.ToString("F3")+"/"+sample.magazine+"/"+sample.accuracy.ToString("F2")+"/"+sample.reloadSeconds.ToString("F3"));}Check(signatures.Count==GunSeriesDesigns.SeriesCount,"twelve mechanically distinct series "+maker+"/"+cls);for(int page=0;page<3;page++){ClearCards();title=ManufacturerCatalog.Id(maker)+" / "+GunSeriesDesigns.ClassName(cls,false)+" / SERIES "+(page*4+1)+"-"+(page*4+4)+" : painting | actual mesh";for(int series=page*4;series<page*4+4;series++){EquipmentRecipe chosen=null;foreach(var candidate in DistinctEquipmentDesigns.Guns)if(!candidate.legendary&&candidate.maker==maker&&candidate.gunClass==cls&&candidate.series==series&&candidate.seriesVariant==0){chosen=candidate;break;}Check(chosen!=null,"class-series representative");if(chosen!=null)Add(chosen,0);}yield return Capture("maker-"+maker+"-class-"+cls+"-series-page-"+page);}}
                var guns=new List<EquipmentRecipe>();for(int body=0;body<6;body++)guns.Add(Find(DistinctEquipmentDesigns.Guns,maker,body,-1,false));foreach(var r in DistinctEquipmentDesigns.Guns)if(r.maker==maker&&r.legendary)guns.Add(r);
                for(int page=0;page<2;page++){ClearCards();title="MAKER "+maker+" / GUNS / "+(page+1)+" : painted illustration | actual Unity mesh";for(int i=page*6;i<Math.Min(page*6+6,guns.Count);i++)Add(guns[i],0);yield return Capture("maker-"+maker+"-guns-"+page);}
